def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def prime_fib(n: int) -> int:
    a, b = 1, 2
    count = 0
    while count < n:
        if is_prime(a):
            count += 1
        a, b = b, a + b
    return a
